const data=await(await fetch('v180-bard-strum.json')).json(),root=document.querySelector('#native-art'),nativePlay=document.querySelector('#native-play'),nativeStop=document.querySelector('#native-stop'),gifPlay=document.querySelector('#gif-play'),gifStop=document.querySelector('#gif-stop'),image=document.querySelector('#gif-art'),status=document.querySelector('#native-status'),gifStatus=document.querySelector('#gif-status'),reduced=matchMedia('(prefers-reduced-motion: reduce)'),poster='../assets/studies/v180-bard-strum-poster.png',gif='../assets/studies/v180-bard-strum.gif';let animations=[],generation=0;
function stop(){generation++;for(const a of animations)a.cancel();animations=[];for(const[key,p]of Object.entries(data.keyframes.parts)){const n=root.querySelector('[data-bard-part="'+key+'"]');n.style.transform=p.settled;n.style.opacity=p.opacity;}root.dataset.playing='false';status.textContent='静态结算姿态 · 原记录3 → 4。';}
function stopGIF(){image.src=poster;image.alt='塞恩持琴的静态结算姿态';gifStatus.textContent='静态图；GIF不能精确暂停到任意帧。';}
nativePlay.addEventListener('click',()=>{if(reduced.matches)return;stop();const seq=++generation;root.dataset.playing='true';status.textContent='正在演示已记录的拨弦；不新增战斗或奖励。';for(const[key,p]of Object.entries(data.keyframes.parts)){const n=root.querySelector('[data-bard-part="'+key+'"]');animations.push(n.animate(p.frames,{duration:data.nativeDurationMs,easing:'linear',fill:'none'}));}Promise.all(animations.map(a=>a.finished.catch(()=>null))).then(()=>{if(seq!==generation)return;stop();status.textContent='动作完成，恢复结算姿态 · 原记录3 → 4。';});});nativeStop.addEventListener('click',stop);gifPlay.addEventListener('click',()=>{if(reduced.matches)return;image.src=gif;image.alt='塞恩拨弦的八帧循环独立样片';gifStatus.textContent='八帧循环1100毫秒，近似原生动作并含末帧停留。';});gifStop.addEventListener('click',stopGIF);
function motionPolicy(){nativePlay.disabled=gifPlay.disabled=reduced.matches;if(reduced.matches){const active=document.activeElement;stop();stopGIF();status.textContent='已减少动态效果，保持静态结算姿态。';if(active===nativePlay)nativeStop.focus({preventScroll:true});if(active===gifPlay)gifStop.focus({preventScroll:true});}}
reduced.addEventListener('change',motionPolicy);addEventListener('pagehide',()=>{stop();stopGIF();});stop();motionPolicy();
